// API Service
export const systemService = {
  // Get current system metrics
  async getMetrics(): Promise<SystemMetrics> {
    await new Promise(resolve => setTimeout(resolve, 300)); // Simulate API delay
    return generateMockData.metrics();
  },

  // Get system health status
  async getHealth(): Promise<SystemHealth> {
    await new Promise(resolve => setTimeout(resolve, 200));
    return generateMockData.health();
  },

  // Get all agents
  async getAgents(): Promise<Agent[]> {
    await new Promise(resolve => setTimeout(resolve, 250));
    return generateMockData.agents();
  },

  // Get observations
  async getObservations(): Promise<SystemObservation[]> {
    await new Promise(resolve => setTimeout(resolve, 200));
    return generateMockData.observations();
  },

  // Get deployments
  async getDeployments(): Promise<Deployment[]> {
    await new Promise(resolve => setTimeout(resolve, 180));
    return generateMockData.deployments();
  },

  // Get alerts
  async getAlerts(): Promise<Alert[]> {
    await new Promise(resolve => setTimeout(resolve, 150));
    return generateMockData.alerts();
  },

  // Get performance metrics
  async getPerformance(): Promise<PerformanceMetric[]> {
    await new Promise(resolve => setTimeout(resolve, 200));
    return generateMockData.performance();
  },

  // Get dashboard stats
  async getStats(): Promise<DashboardStats> {
    await new Promise(resolve => setTimeout(resolve, 150));
    return generateMockData.stats();
  },

  // Simulate agent action
  async performAgentAction(agentId: string, action: string): Promise<{ success: boolean; message: string }> {
    await new Promise(resolve => setTimeout(resolve, 500));
    return {
      success: true,
      message: `Action '${action}' completed on agent ${agentId}`
    };
  },

  // Simulate deployment action
  async performDeploymentAction(deploymentId: string, action: string): Promise<{ success: boolean; message: string }> {
    await new Promise(resolve => setTimeout(resolve, 800));
    return {
      success: true,
      message: `Deployment ${action} completed for ${deploymentId}`
    };
  },

  // Export data
  async exportData(format: 'csv' | 'json'): Promise<string> {
    await new Promise(resolve => setTimeout(resolve, 600));
    const data = generateMockData.stats();
    return format === 'json' 
      ? JSON.stringify(data, null, 2)
      : Object.keys(data).map(k => `${k},${data[k as keyof DashboardStats]}`).join('\n');
  }
};